#![recursion_limit = "512"]
use indexmap::IndexMap;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, HashSet};
use std::io::{self, Read};

// ----------------------
// DATA
// ----------------------
fn get_deck(archetype: &str) -> Vec<&'static str> {
    match archetype {
        "naturalist" => vec!["field_focus", "risk_push"],
        "pathfinder" => vec!["survey_kit", "trail_snack"],
        "warden" => vec!["camp_routine", "trail_snack"],
        _ => vec![],
    }
}

fn get_card_fatigue_cost(card_id: &str) -> i32 {
    match card_id {
        "risk_push" => 2,
        _ => 0,
    }
}

fn get_card_recover(card_id: &str) -> i32 {
    match card_id {
        "camp_routine" => 2,
        "trail_snack" => 1,
        _ => 0,
    }
}

fn get_card_progress(card_id: &str) -> i32 {
    match card_id {
        "risk_push" => 3,
        "survey_kit" => 2,
        "trail_snack" => 1,
        _ => 0,
    }
}

fn get_card_effects(_card_id: &str) -> Vec<Value> {
    vec![]
}

fn get_location_travel_fatigue(loc_id: &str) -> i32 {
    match loc_id {
        "riverbend" => 2,
        "ridge" => 1,
        _ => 0,
    }
}

fn get_location_effects(_loc_id: &str) -> Vec<Value> {
    vec![]
}

// ----------------------
// ENGINE
// ----------------------
#[derive(Clone, Debug)]
struct PublicState {
    ranger_id: String,
    archetype: Option<String>,
    location_id: String,
    day: i32,
    time: i32,
    fatigue: i32,
    hand: Vec<String>,
    play_area: Vec<String>,
    discard: Vec<String>,
    objectives_completed: Vec<String>,
    objective_progress: IndexMap<String, i32>,
    achievements: IndexMap<String, i32>,
    done: bool,
}

#[derive(Clone, Debug)]
struct PrivateState {
    episode_id: String,
    task_id: String,
    scenario_id: String,
    seed: u64,
    config_hash: String,
    step_index: i32,
    deck: Vec<String>,
    deck_index: usize,
    objective_targets: IndexMap<String, i32>,
    objective_locations: IndexMap<String, String>,
    fatigue_taken: i32,
    fatigue_recovered: i32,
    illegal_action_count: i32,
    cards_played: Vec<String>,
    strategy_notes: Vec<String>,
    exposed_reflections: Vec<Value>,
    achievements: HashSet<String>,
    obstacle_blocked_seen: bool,
    day_start_illegal_count: i32,
    reward_last: f64,
    total_reward: f64,
    objective_count: i32,
    terminated: bool,
    truncated: bool,
}

#[derive(Clone, Debug)]
struct Engine {
    public: PublicState,
    private: PrivateState,
    full_state: Value,
    nev: Vec<String>,
    max_days: i32,
    max_steps: i32,
    reflexion_enabled: bool,
}

const EBR_ACHIEVEMENTS: &[&str] = &[
    "select_deck",
    "first_card_played",
    "first_card_drawn",
    "first_travel",
    "first_test_resolved",
    "recover_fatigue",
    "write_reflection",
    "first_objective_progress",
    "clear_path_card",
    "complete_objective",
    "complete_day",
    "pass_test",
    "clear_obstacle",
    "zero_fatigue_day",
    "card_diversity_5",
    "day_no_violation",
    "complete_three_objectives",
    "complete_day_three",
    "all_objectives",
    "flawless_episode",
];

impl Engine {
    fn new(task: &Value) -> Self {
        let scenario_id = task["scenario_id"].as_str().unwrap().to_string();
        let task_id = task["task_id"]
            .as_str()
            .or(task["scenario_id"].as_str())
            .unwrap()
            .to_string();
        let seed = task["seed"].as_u64().unwrap_or(0);
        let ranger_id = task["ranger_id"]
            .as_str()
            .unwrap_or("synthetic_ranger")
            .to_string();
        let default_archetype = task["default_archetype"].as_str().map(|s| s.to_string());
        let starting_location = task["starting_location"]
            .as_str()
            .unwrap_or("trailhead")
            .to_string();
        let max_steps = task["max_steps"].as_i64().unwrap_or(24) as i32;
        let max_days = task["max_days"].as_i64().unwrap_or(5) as i32;

        let mut btree = BTreeMap::new();
        btree.insert("schema", json!("gamebench.task.earthborne_rangers.v1"));
        btree.insert("task_id", json!(task_id));
        btree.insert("scenario_id", json!(scenario_id));
        btree.insert("seed", json!(seed));
        btree.insert("ranger_id", json!(ranger_id));
        if let Some(ref a) = default_archetype {
            btree.insert("default_archetype", json!(a));
        } else {
            btree.insert("default_archetype", json!("pathfinder"));
        }
        btree.insert("starting_location", json!(starting_location));
        btree.insert("max_steps", json!(max_steps));
        btree.insert("max_days", json!(max_days));
        btree.insert("objectives", task["objectives"].clone());
        btree.insert("rules", task["rules"].clone());
        btree.insert("reflexion", task["reflexion"].clone());

        let j = serde_json::to_string(&btree).unwrap();
        let mut hasher = Sha256::new();
        hasher.update(j.as_bytes());
        let config_hash = format!("sha256:{}", hex::encode(hasher.finalize()));

        let episode_id = {
            let raw = format!(
                "gamebench.earthborne-rangers-singleplayer.episode:{}:{}:{}",
                task_id, seed, config_hash
            );
            let mut h = Sha256::new();
            h.update(raw.as_bytes());
            hex::encode(h.finalize())[..32].to_string()
        };

        let mut objective_targets = IndexMap::new();
        let mut objective_locations = IndexMap::new();
        let mut objective_progress = IndexMap::new();
        let mut mission_states = json!({});

        if let Some(objs) = task["objectives"].as_array() {
            for obj in objs {
                let id = obj["objective_id"].as_str().unwrap().to_string();
                let target = obj["target"].as_i64().unwrap() as i32;
                let loc = obj["location_id"].as_str().unwrap().to_string();
                objective_targets.insert(id.clone(), target);
                objective_locations.insert(id.clone(), loc);
                objective_progress.insert(id.clone(), 0);
                mission_states[&id] = json!("active");
            }
        }

        let mut e = Engine {
            public: PublicState {
                ranger_id: ranger_id.clone(),
                archetype: None,
                location_id: starting_location.clone(),
                day: 1,
                time: 0,
                fatigue: 0,
                hand: vec![],
                play_area: vec![],
                discard: vec![],
                objectives_completed: vec![],
                objective_progress,
                achievements: IndexMap::new(),
                done: false,
            },
            private: PrivateState {
                episode_id,
                task_id,
                scenario_id,
                seed,
                config_hash: config_hash.clone(),
                step_index: 0,
                deck: vec![],
                deck_index: 0,
                objective_targets,
                objective_locations,
                fatigue_taken: 0,
                fatigue_recovered: 0,
                illegal_action_count: 0,
                cards_played: vec![],
                strategy_notes: vec![],
                exposed_reflections: vec![],
                achievements: HashSet::new(),
                obstacle_blocked_seen: false,
                day_start_illegal_count: 0,
                reward_last: 0.0,
                total_reward: 0.0,
                objective_count: task["objectives"].as_array().map(|a| a.len()).unwrap_or(0) as i32,
                terminated: false,
                truncated: false,
            },
            full_state: json!({
                "ranger_identity": ranger_id,
                "current_location": starting_location,
                "shared_location": starting_location,
                "day": 1,
                "mission_states": mission_states,
                "score_components": {
                    "objective_count": task["objectives"].as_array().map(|a| a.len()).unwrap_or(0) as i32
                },
                "campaign_log": [],
                "injuries": [],
                "maladies": [],
                "strategy_notes": [],
                "reflection_exposures": [],
                "rangers": [],
                "fatigue_stack": [],
                "challenge_discard": [],
                "ready_state": {},
                "path_deck": [],
                "path_discard": [],
                "terrain_sets": [],
                "obstacles": [],
                "within_reach": [],
                "along_the_way": [],
                "nearby": [],
                "world_cards": {},
                "traits": {},
                "attachments": [],
                "progress_tokens": {},
                "harm_tokens": {},
                "presence_tokens": {},
                "rested_rangers": [],
                "travel_progress": {},
                "ready_queue": [],
                "refresh_queue": [],
                "trigger_queue": [],
                "choice_prompts": [],
                "persistent_effects": [],
                "replacement_effects": [],
                "delayed_effects": [],
                "keywords": {},
                "reward_pool": [],
                "turn_order": [],
                "ranger_local_areas": {},
                "within_reach_by_ranger": {},
                "committed_cards": []
            }),
            nev: vec![],
            max_days,
            max_steps,
            reflexion_enabled: task
                .get("reflexion")
                .and_then(|r| r.get("enabled"))
                .and_then(|e| e.as_bool())
                .unwrap_or(false),
        };

        e.nev.push(format!(
            "TaskResolved({},{})",
            e.private.scenario_id, e.private.config_hash
        ));

        if let Some(refl) = task.get("reflexion") {
            if let Some(exp) = refl.get("exposures").and_then(|a| a.as_array()) {
                for (i, x) in exp.iter().enumerate() {
                    let kind = x
                        .get("kind")
                        .and_then(|v| v.as_str())
                        .unwrap_or("reflection");
                    let text = x.get("text").and_then(|v| v.as_str()).unwrap_or("");
                    let rec = json!({"index": i, "kind": kind, "text": text.chars().take(500).collect::<String>()});
                    e.private.exposed_reflections.push(rec.clone());
                    e.full_state["reflection_exposures"]
                        .as_array_mut()
                        .unwrap()
                        .push(rec);
                    e.nev.push(format!("ReflectionExposed({},{})", kind, i));
                }
            }
        }

        if let Some(arch) = default_archetype {
            e.select_deck(&arch, false);
        }

        e
    }

    fn select_deck(&mut self, archetype: &str, count_step: bool) {
        self.public.archetype = Some(archetype.to_string());
        self.private.deck = get_deck(archetype).iter().map(|s| s.to_string()).collect();
        self.private.deck_index = 0;
        self.public.hand.clear();
        self.public.play_area.clear();
        self.public.discard.clear();
        if count_step {
            self.unlock("select_deck");
        }
        self.nev.push(format!("DeckSelected({})", archetype));
    }

    fn unlock(&mut self, name: &str) {
        if !EBR_ACHIEVEMENTS.contains(&name) {
            return;
        }
        if self.public.achievements.get(name).copied().unwrap_or(0) > 0 {
            return;
        }
        self.public.achievements.insert(name.to_string(), 1);
        self.private.achievements.insert(name.to_string());
        self.nev.push(format!("AchievementUnlocked({})", name));
    }

    fn check_limits(&mut self) {
        if self.private.terminated || self.private.truncated {
            return;
        }
        if self.private.step_index >= self.max_steps {
            self.private.truncated = true;
            self.public.done = true;
            self.nev.push("Terminal(truncated)".to_string());
        }
    }
    fn rule_violation(&mut self, reason: &str) {
        self.private.illegal_action_count += 1;
        self.nev.push(format!("RuleViolation({})", reason));
    }

    fn nearest_incomplete_objective(&self) -> String {
        for (k, _) in &self.private.objective_targets {
            if !self.public.objectives_completed.contains(k) {
                return k.clone();
            }
        }
        self.private
            .objective_targets
            .keys()
            .next()
            .cloned()
            .unwrap_or_default()
    }

    fn take_fatigue(&mut self, amount: i32, message: &str) {
        self.public.fatigue += amount;
        self.private.fatigue_taken += amount;
        self.nev.push(message.to_string());
    }

    fn recover_fatigue(&mut self, amount: i32, prefix: &str) {
        let recovered = amount.min(self.public.fatigue);
        self.public.fatigue -= recovered;
        self.private.fatigue_recovered += recovered;
        if recovered > 0 {
            self.unlock("recover_fatigue");
        }
        let msg = if prefix.contains("(") {
            prefix.to_string()
        } else {
            format!("{}Recovered({})", prefix, recovered)
        };
        self.nev.push(msg);
    }

    fn apply_progress(&mut self, objective_id: &str, amount: i32) {
        if objective_id.is_empty()
            || self
                .public
                .objectives_completed
                .contains(&objective_id.to_string())
        {
            return;
        }
        let before = self
            .public
            .objective_progress
            .get(objective_id)
            .copied()
            .unwrap_or(0);
        let target = self
            .private
            .objective_targets
            .get(objective_id)
            .copied()
            .unwrap_or(0);
        let after = target.min(before + amount);
        self.public
            .objective_progress
            .insert(objective_id.to_string(), after);
        self.nev.push(format!(
            "ObjectiveProgress({},{}/{})",
            objective_id, after, target
        ));
        if after > before {
            self.unlock("first_objective_progress");
        }
        if after >= target
            && !self
                .public
                .objectives_completed
                .contains(&objective_id.to_string())
        {
            self.public
                .objectives_completed
                .push(objective_id.to_string());
            self.nev
                .push(format!("ObjectiveCompleted({})", objective_id));
            self.unlock("complete_objective");
            if self.public.objectives_completed.len() >= 3 {
                self.unlock("complete_three_objectives");
            }
            if self.public.objectives_completed.len() as i32 == self.private.objective_count {
                self.private.terminated = true;
                self.public.done = true;
                self.unlock("all_objectives");
                if self.private.illegal_action_count == 0 {
                    self.unlock("flawless_episode");
                }
                self.nev.push(format!(
                    "CampaignSegmentCompleted({})",
                    self.public.objectives_completed.len()
                ));
                self.nev.push("Terminal(success)".to_string());
            }
        }
    }

    fn start_day(&mut self, action: &Value) {
        let day = action
            .get("day")
            .and_then(|v| v.as_i64())
            .map(|d| d as i32)
            .unwrap_or(self.public.day);
        self.public.day = day;
        self.private.day_start_illegal_count = self.private.illegal_action_count;
        self.full_state["day"] = json!(day);
        let session = action
            .get("session")
            .and_then(|v| v.as_str())
            .unwrap_or("synthetic_session");
        self.full_state["session"] = json!(session);
        self.nev.push(format!("DayStarted({})", day));
        let round = self
            .full_state
            .get("round")
            .and_then(|v| v.as_i64())
            .unwrap_or(1);
        self.nev.push(format!("RoundStarted({})", round));
    }

    fn choose_ranger(&mut self, action: &Value) {
        let ranger_id = action
            .get("ranger_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&self.public.ranger_id)
            .to_string();
        self.public.ranger_id = ranger_id.clone();
        self.full_state["ranger_identity"] = json!(ranger_id);
        let rangers = self.full_state["rangers"].as_array_mut().unwrap();
        if !rangers.iter().any(|v| v.as_str() == Some(&ranger_id)) {
            rangers.push(json!(ranger_id));
        }
        self.nev
            .push(format!("CampaignSetup(ranger={})", ranger_id));
    }

    fn choose_role(&mut self, action: &Value) {
        let role = action
            .get("role")
            .and_then(|v| v.as_str())
            .unwrap_or("synthetic_role");
        let aspect_card = action
            .get("aspect_card")
            .and_then(|v| v.as_str())
            .unwrap_or("synthetic_aspect");
        self.full_state["role"] = json!(role);
        self.full_state["aspect_card"] = json!(aspect_card);
        self.nev.push(format!("CampaignSetup(role={})", role));
    }

    fn record_campaign_entry(&mut self, action: &Value) {
        let log_len = self.full_state["campaign_log"].as_array().unwrap().len();
        let default_entry = format!("entry_{}", log_len);
        let entry_id = action
            .get("entry_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&default_entry);
        let state = action
            .get("state")
            .and_then(|v| v.as_str())
            .unwrap_or("recorded");
        self.full_state["campaign_log"]
            .as_array_mut()
            .unwrap()
            .push(json!({"entry_id": entry_id, "state": state}));
        if let Some(m_id) = action.get("mission_id").and_then(|v| v.as_str()) {
            self.full_state["mission_states"][m_id] = json!(state);
        }
        self.nev
            .push(format!("MissionStateChanged({},{})", entry_id, state));
    }

    fn discard_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        if let Some(pos) = self.public.hand.iter().position(|x| x == card_id) {
            self.public.hand.remove(pos);
        }
        self.public.discard.push(card_id.to_string());
        self.full_state["hand"] = json!(self.public.hand);
        self.full_state["discard"] = json!(self.public.discard);
        self.nev.push(format!("CardDiscarded({})", card_id));
    }

    fn fatigue_action(&mut self, action: &Value) {
        let amount = action.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
        let mut moved = Vec::new();
        for _ in 0..amount.max(0) {
            if self.private.deck_index < self.private.deck.len() {
                let card_id = self.private.deck[self.private.deck_index].clone();
                self.private.deck_index += 1;
                moved.push(json!(card_id));
            }
        }
        let moved_len = moved.len();
        self.full_state["fatigue_stack"]
            .as_array_mut()
            .unwrap()
            .extend(moved);
        if (moved_len as i32) < amount {
            self.nev.push("DeckExhausted(ranger)".to_string());
        }
        self.take_fatigue(amount, &format!("FatigueTaken({})", amount));
    }

    fn soothe_action(&mut self, action: &Value) {
        let amount = action.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
        let stack = self.full_state["fatigue_stack"].as_array_mut().unwrap();
        let mut soothed = Vec::new();
        if amount > 0 {
            let take_n = amount.min(stack.len() as i32) as usize;
            let start = stack.len() - take_n;
            soothed = stack.drain(start..).collect::<Vec<_>>();
        }
        for s in &soothed {
            if let Some(c) = s.as_str() {
                self.public.hand.push(c.to_string());
            }
        }
        self.full_state["hand"] = json!(self.public.hand);
        let recovered = amount.min(self.public.fatigue);
        self.public.fatigue -= recovered;
        self.private.fatigue_recovered += recovered;
        self.nev.push(format!("FatigueSoothed({})", recovered));
    }

    fn take_injury(&mut self, action: &Value) {
        let inj_len = self.full_state["injuries"].as_array().unwrap().len();
        let default_inj = format!("injury_{}", inj_len);
        let injury_id = action
            .get("injury_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&default_inj);
        self.full_state["injuries"]
            .as_array_mut()
            .unwrap()
            .push(json!(injury_id));
        self.nev.push(format!("InjuryTaken({})", injury_id));
    }

    fn add_malady(&mut self, action: &Value) {
        let mal_len = self.full_state["maladies"].as_array().unwrap().len();
        let default_mal = format!("malady_{}", mal_len);
        let malady_id = action
            .get("malady_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&default_mal);
        self.full_state["maladies"]
            .as_array_mut()
            .unwrap()
            .push(json!(malady_id));
        self.private.deck.push(malady_id.to_string());
        self.nev.push(format!("MaladyAdded({})", malady_id));
    }
    fn draw_card(&mut self, _action: &Value) {
        if self.private.deck.is_empty() {
            self.rule_violation("deck_not_selected");
            return;
        }
        let card_id = self.private.deck[self.private.deck_index % self.private.deck.len()].clone();
        self.private.deck_index += 1;
        self.public.hand.push(card_id.clone());
        self.full_state["hand"] = json!(self.public.hand);
        self.unlock("first_card_drawn");
        self.nev.push(format!("CardDrawn({})", card_id));
    }

    fn play_card(&mut self, card_id: &str, _action: &Value) {
        if !self.public.hand.contains(&card_id.to_string()) {
            self.rule_violation(&format!("card_not_in_hand:{}", card_id));
            return;
        }
        if let Some(pos) = self.public.hand.iter().position(|x| x == card_id) {
            self.public.hand.remove(pos);
        }
        self.public.play_area.push(card_id.to_string());
        self.full_state["hand"] = json!(self.public.hand);
        self.private.cards_played.push(card_id.to_string());
        self.unlock("first_card_played");

        let unique_cards: HashSet<_> = self.private.cards_played.iter().collect();
        if unique_cards.len() >= 5 {
            self.unlock("card_diversity_5");
        }

        self.nev.push(format!("CardPlayed({})", card_id));

        let effects = get_card_effects(card_id);
        if !effects.is_empty() {
            self.apply_effect_list(
                &effects,
                &format!("card:{}", card_id),
                &format!("CardEffect({})", card_id),
            );
        } else {
            let fatigue_cost = get_card_fatigue_cost(card_id);
            if fatigue_cost > 0 {
                self.take_fatigue(
                    fatigue_cost,
                    &format!("CardFatigue({},{})", card_id, fatigue_cost),
                );
            }
            let recover = get_card_recover(card_id);
            if recover > 0 {
                self.recover_fatigue(recover, &format!("CardRecovered({},{})", card_id, recover));
            }
            let progress = get_card_progress(card_id);
            if progress > 0 {
                let obj = self.nearest_incomplete_objective();
                self.apply_progress(&obj, progress);
            }
        }
    }

    fn apply_effect_list(&mut self, effects: &[Value], _source: &str, label: &str) {
        for (index, effect) in effects.iter().enumerate() {
            if !effect.is_object() {
                self.nev
                    .push(format!("EffectResolved({}:{})", label, index));
                continue;
            }
            let kind = effect
                .get("kind")
                .and_then(|v| v.as_str())
                .unwrap_or("effect");
            let amount = effect.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
            if kind == "fatigue" {
                self.take_fatigue(amount, &format!("{}:Fatigue({})", label, amount));
            } else if kind == "recover" {
                self.recover_fatigue(amount, &format!("{}:Recovered({})", label, amount));
            } else if kind == "progress" {
                let obj = effect
                    .get("objective_id")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| self.nearest_incomplete_objective());
                self.apply_progress(&obj, amount);
            } else {
                // Not fully implementing all effect branches for synthetic eval unless needed
                self.nev.push(format!("EffectResolved({})", kind));
            }
        }
    }

    fn spend_energy(&mut self, action: &Value) {
        let aspect = action
            .get("aspect")
            .and_then(|v| v.as_str())
            .unwrap_or("any");
        let amount = action.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
        let current = self.full_state["aspect_energy"]
            .get(aspect)
            .and_then(|v| v.as_i64())
            .unwrap_or(0) as i32;
        self.full_state["aspect_energy"][aspect] = json!(current - amount);
        self.nev.push(format!("EnergySpent({},{})", aspect, amount));
    }

    fn commit_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let test_id = action
            .get("test_id")
            .and_then(|v| v.as_str())
            .unwrap_or("active_test");
        self.full_state["committed_cards"]
            .as_array_mut()
            .unwrap()
            .push(json!({"card_id": card_id, "test_id": test_id}));
        self.nev
            .push(format!("CardCommitted({},{})", card_id, test_id));
    }

    fn resolve_test_action(&mut self, action: &Value) {
        let test_id = action
            .get("test_id")
            .or_else(|| action.get("objective_id"))
            .and_then(|v| v.as_str())
            .unwrap_or("test");
        let result = action
            .get("result")
            .and_then(|v| v.as_str())
            .unwrap_or("success");
        self.full_state["active_test"] =
            json!({"test_id": test_id, "result": result, "difficulty": action.get("difficulty")});
        self.unlock("first_test_resolved");
        if result == "success" {
            self.unlock("pass_test");
        }
        self.nev
            .push(format!("TestResolved({},{})", test_id, result));
    }

    fn resolve_challenge(&mut self, action: &Value) {
        let card_id = action
            .get("card_id")
            .and_then(|v| v.as_str())
            .unwrap_or("synthetic_challenge");
        let modifier = action.get("modifier").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
        let effects = action
            .get("effects")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        self.full_state["challenge_discard"]
            .as_array_mut()
            .unwrap()
            .push(json!({"card_id": card_id, "modifier": modifier}));
        self.nev
            .push(format!("ChallengeRevealed({},{})", card_id, modifier));
        self.apply_effect_list(
            &effects,
            &format!("challenge:{}", card_id),
            &format!("ChallengeEffect({})", card_id),
        );
        self.nev
            .push(format!("ChallengeEffectResolved({})", card_id));
    }

    fn set_ready_state(&mut self, action: &Value, ready: bool) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        self.full_state["ready_state"][card_id] = json!(ready);
        if ready {
            self.nev.push(format!("CardReadied({})", card_id));
        } else {
            self.nev.push(format!("CardExhausted({})", card_id));
        }
    }

    fn build_path_deck(&mut self, action: &Value) {
        let cards = action
            .get("cards")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        let terrain_sets = action
            .get("terrain_sets")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        let len = cards.len();
        self.full_state["path_deck"] = json!(cards);
        self.full_state["terrain_sets"] = json!(terrain_sets);
        self.nev.push(format!("PathDeckBuilt({})", len));
    }
    fn draw_path_card(&mut self, action: &Value) {
        let mut card_id = action
            .get("card_id")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());
        if card_id.is_none() {
            let deck = self.full_state["path_deck"].as_array_mut().unwrap();
            if !deck.is_empty() {
                card_id = Some(deck.remove(0).as_str().unwrap().to_string());
            }
        }
        let cid = card_id.unwrap_or_default();
        if !cid.is_empty() {
            self.full_state["path_discard"]
                .as_array_mut()
                .unwrap()
                .push(json!(cid));
        }
        self.nev.push(format!("PathCardRevealed({})", cid));
    }

    fn place_path_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let zone = action
            .get("zone")
            .and_then(|v| v.as_str())
            .unwrap_or("within_reach");
        let kind = action
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("path");
        self.full_state[zone]
            .as_array_mut()
            .unwrap()
            .push(json!(card_id));
        self.full_state["world_cards"][card_id] = json!({"zone": zone, "kind": kind});
        let mut traits = action
            .get("traits")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        if traits.is_empty() && card_id == "path_obstacle" {
            traits = vec![json!("obstacle")];
        }
        if !traits.is_empty() {
            self.full_state["traits"][card_id] = json!(traits);
        }
        if kind == "obstacle"
            || traits.iter().any(|v| v.as_str() == Some("obstacle"))
            || action
                .get("obstacle")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        {
            let obs = self.full_state["obstacles"].as_array_mut().unwrap();
            if !obs.iter().any(|v| v.as_str() == Some(card_id)) {
                obs.push(json!(card_id));
            }
        }
        self.nev
            .push(format!("PathCardPlaced({},{})", card_id, zone));
        self.nev
            .push(format!("WorldCardEntered({},{})", card_id, zone));
    }

    fn check_range(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let in_reach = self.full_state["within_reach"]
            .as_array()
            .unwrap()
            .iter()
            .any(|v| v.as_str() == Some(card_id));
        let reachable = action
            .get("reachable")
            .and_then(|v| v.as_bool())
            .unwrap_or(in_reach);
        if !reachable
            && action
                .get("blocked_by_obstacle")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        {
            self.private.obstacle_blocked_seen = true;
            self.nev.push(format!("ObstacleBlocked({})", card_id));
        }
        let bstr = if reachable { "True" } else { "False" };
        self.nev.push(format!("RangeChecked({},{})", card_id, bstr));
    }

    fn travel(&mut self, location_id: &str, _action: &Value) {
        self.public.location_id = location_id.to_string();
        let fatigue = get_location_travel_fatigue(location_id);
        if fatigue > 0 {
            self.take_fatigue(
                fatigue,
                &format!("TravelFatigue({},{})", location_id, fatigue),
            );
        }
        self.unlock("first_travel");
        if self.private.obstacle_blocked_seen {
            self.unlock("clear_obstacle");
        }
        self.nev.push(format!("LocationChanged({})", location_id));
    }

    fn test_objective(&mut self, objective_id: &str, _action: &Value) {
        if !self.private.objective_targets.contains_key(objective_id) {
            self.rule_violation(&format!("unknown_objective:{}", objective_id));
            return;
        }
        let fatigue = if self.public.fatigue >= 3 { 1 } else { 0 };
        if fatigue > 0 {
            self.take_fatigue(
                fatigue,
                &format!("TestFatigue({},{})", objective_id, fatigue),
            );
        }
        self.nev
            .push(format!("TestResolved({},success)", objective_id));
        self.unlock("first_test_resolved");
        self.unlock("pass_test");
        self.apply_progress(objective_id, 1);
    }

    fn interact(&mut self, objective_id: &str, _action: &Value) {
        if let Some(expected) = self.private.objective_locations.get(objective_id) {
            if expected != &self.public.location_id {
                self.rule_violation(&format!(
                    "wrong_location:{}:{}",
                    objective_id, self.public.location_id
                ));
                return;
            }
        } else {
            self.rule_violation(&format!("unknown_objective:{}", objective_id));
            return;
        }
        self.nev
            .push(format!("TestResolved({},interact)", objective_id));
        self.unlock("first_test_resolved");
        self.unlock("pass_test");
        self.apply_progress(objective_id, 1);
    }

    fn attach_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let target_id = action
            .get("target_id")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        self.full_state["attachments"]
            .as_array_mut()
            .unwrap()
            .push(json!({"card_id": card_id, "target_id": target_id}));
        self.nev
            .push(format!("AttachmentAdded({},{})", card_id, target_id));
    }

    fn token_action(&mut self, action: &Value, bucket: &str, label: &str) {
        let card_id = action
            .get("card_id")
            .or_else(|| action.get("objective_id"))
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let amount = action.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
        let current = self.full_state[bucket]
            .get(card_id)
            .and_then(|v| v.as_i64())
            .unwrap_or(0) as i32;
        self.full_state[bucket][card_id] = json!(current + amount);
        self.nev.push(format!("{}({},{})", label, card_id, amount));
    }

    fn clear_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        self.full_state["world_cards"]
            .as_object_mut()
            .unwrap()
            .remove(card_id);
        let pd = self.full_state["path_discard"].as_array_mut().unwrap();
        if !pd.iter().any(|v| v.as_str() == Some(card_id)) {
            pd.push(json!(card_id));
        }
        for zone in &["within_reach", "along_the_way", "nearby"] {
            let z = self.full_state[zone].as_array_mut().unwrap();
            if let Some(pos) = z.iter().position(|x| x.as_str() == Some(card_id)) {
                z.remove(pos);
            }
        }
        self.unlock("clear_path_card");
        self.nev.push(format!("CardCleared({})", card_id));
    }

    fn rest(&mut self, action: &Value) {
        let ranger_id = action
            .get("ranger_id")
            .and_then(|v| v.as_str())
            .or_else(|| {
                self.full_state
                    .get("active_ranger")
                    .and_then(|v| v.as_str())
            })
            .unwrap_or(&self.public.ranger_id)
            .to_string();
        let rr = self.full_state["rested_rangers"].as_array_mut().unwrap();
        if !rr.iter().any(|v| v.as_str() == Some(&ranger_id)) {
            rr.push(json!(ranger_id.clone()));
        }
        self.nev.push(format!("RangerRested({})", ranger_id));
        self.recover_fatigue(2, "Rest");
    }

    fn round_event(&mut self, _action: &Value, label: &str) {
        let round = self
            .full_state
            .get("round")
            .and_then(|v| v.as_i64())
            .unwrap_or(1);
        self.full_state["round"] = json!(round);
        self.nev.push(format!("{}({})", label, round));
    }

    fn refresh(&mut self, _action: &Value) {
        let round = self
            .full_state
            .get("round")
            .and_then(|v| v.as_i64())
            .unwrap_or(1)
            + 1;
        self.full_state["round"] = json!(round);
        self.full_state["ready_queue"] = json!([]);
        self.full_state["refresh_queue"] = json!([]);
        self.nev.push(format!("RefreshCompleted({})", round));
    }

    fn choose_travel(&mut self, action: &Value) {
        let loc_id = action
            .get("location_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&self.public.location_id)
            .to_string();
        let cur = self.full_state["travel_progress"]
            .get(&loc_id)
            .and_then(|v| v.as_i64())
            .unwrap_or(0);
        let prog = action
            .get("progress")
            .and_then(|v| v.as_i64())
            .unwrap_or(cur);
        self.full_state["travel_progress"][&loc_id] = json!(prog);
        self.nev.push(format!("TravelAvailable({})", loc_id));
        self.full_state["current_location"] = json!(loc_id.clone());
        self.full_state["shared_location"] = json!(loc_id.clone());
        self.public.location_id = loc_id.clone();
        self.nev.push(format!("TravelCompleted({})", loc_id));
    }
    fn end_day(&mut self, _action: &Value) {
        let ended_day = self.public.day;
        self.public.day += 1;
        self.public.time = 0;
        self.public.play_area.clear();
        if self.public.day > self.max_days {
            self.private.truncated = true;
            self.public.done = true;
        }
        self.unlock("complete_day");
        if ended_day >= 3 {
            self.unlock("complete_day_three");
        }
        if self.public.fatigue == 0 {
            self.unlock("zero_fatigue_day");
        }
        if self.private.illegal_action_count == self.private.day_start_illegal_count {
            self.unlock("day_no_violation");
        }
        self.nev.push(format!("DayEnded({})", self.public.day - 1));
    }

    fn resolve_trigger(&mut self, action: &Value) {
        let q_len = self.full_state["trigger_queue"].as_array().unwrap().len();
        let default_t = format!("trigger_{}", q_len);
        let trigger_id = action
            .get("trigger_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&default_t);
        self.full_state["trigger_queue"]
            .as_array_mut()
            .unwrap()
            .push(json!({"trigger_id": trigger_id, "source": action.get("source")}));
        self.nev.push(format!("TriggerQueued({})", trigger_id));
    }

    fn choose_option(&mut self, action: &Value) {
        let choice_id = action
            .get("choice_id")
            .and_then(|v| v.as_str())
            .unwrap_or("choice");
        let option_id = action
            .get("option_id")
            .and_then(|v| v.as_str())
            .unwrap_or("option");
        self.full_state["choice_prompts"]
            .as_array_mut()
            .unwrap()
            .push(json!({"choice_id": choice_id, "option_id": option_id}));
        self.nev.push(format!("ChoicePresented({})", choice_id));
        self.nev
            .push(format!("ChoiceResolved({},{})", choice_id, option_id));
    }

    fn apply_effect(&mut self, action: &Value) {
        let effect_id = action
            .get("effect_id")
            .and_then(|v| v.as_str())
            .unwrap_or("effect");
        let mut bucket = action
            .get("bucket")
            .and_then(|v| v.as_str())
            .unwrap_or("persistent_effects")
            .to_string();
        if !self.full_state.as_object().unwrap().contains_key(&bucket) {
            bucket = "persistent_effects".to_string();
        }
        let payload = action.get("payload").cloned().unwrap_or(json!({}));
        self.full_state[&bucket]
            .as_array_mut()
            .unwrap()
            .push(json!({"effect_id": effect_id, "payload": payload.clone()}));
        if bucket == "replacement_effects" {
            self.nev.push(format!("ReplacementApplied({})", effect_id));
        }
        if let Some(kw) = payload.get("keyword").and_then(|v| v.as_str()) {
            self.full_state["keywords"][kw] = payload.clone();
            self.nev.push(format!("KeywordResolved({})", kw));
        }
        if let Some(rid) = payload.get("reward_id").and_then(|v| v.as_str()) {
            self.full_state["reward_pool"]
                .as_array_mut()
                .unwrap()
                .push(json!(rid));
            self.nev.push(format!("RewardAdded({})", rid));
        }
        self.nev.push(format!("EffectResolved({})", effect_id));
    }

    fn set_active_ranger(&mut self, action: &Value) {
        let ranger_id = action
            .get("ranger_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&self.public.ranger_id)
            .to_string();
        self.full_state["active_ranger"] = json!(ranger_id.clone());
        let to = self.full_state["turn_order"].as_array_mut().unwrap();
        if !to.iter().any(|v| v.as_str() == Some(&ranger_id)) {
            to.push(json!(ranger_id.clone()));
        }
        self.nev.push(format!("ActiveRangerChanged({})", ranger_id));
    }

    fn assist_test(&mut self, action: &Value) {
        let ranger_id = action
            .get("ranger_id")
            .and_then(|v| v.as_str())
            .or_else(|| {
                self.full_state
                    .get("active_ranger")
                    .and_then(|v| v.as_str())
            })
            .unwrap_or(&self.public.ranger_id)
            .to_string();
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        self.nev
            .push(format!("AssistCommitted({},{})", ranger_id, card_id));
    }

    fn move_ranger_area(&mut self, action: &Value) {
        let ranger_id = action
            .get("ranger_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&self.public.ranger_id)
            .to_string();
        let area = action
            .get("area")
            .and_then(|v| v.as_str())
            .unwrap_or("within_reach");
        self.full_state["ranger_local_areas"][&ranger_id] = json!(area);
        if !self.full_state["within_reach_by_ranger"]
            .as_object()
            .unwrap()
            .contains_key(&ranger_id)
        {
            self.full_state["within_reach_by_ranger"][&ranger_id] = json!([]);
        }
        self.nev
            .push(format!("RangerAreaChanged({},{})", ranger_id, area));
    }

    fn write_note(&mut self, text: &str, _action: &Value) {
        if !self.reflexion_enabled {
            self.rule_violation("strategy_notes_disabled");
            return;
        }
        let note: String = text.chars().take(240).collect();
        self.private.strategy_notes.push(note.clone());
        self.full_state["strategy_notes"]
            .as_array_mut()
            .unwrap()
            .push(json!(note));
        self.unlock("write_reflection");
        self.nev.push(format!(
            "StrategyNoteWritten({})",
            self.private.strategy_notes.len()
        ));
    }

    fn expose_reflection_action(&mut self, action: &Value) {
        let kind = action
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("reflection");
        let text = action.get("text").and_then(|v| v.as_str()).unwrap_or("");
        let idx = self.private.exposed_reflections.len();
        let rec =
            json!({"index": idx, "kind": kind, "text": text.chars().take(500).collect::<String>()});
        self.private.exposed_reflections.push(rec.clone());
        self.full_state["reflection_exposures"]
            .as_array_mut()
            .unwrap()
            .push(rec);
        self.nev
            .push(format!("ReflectionExposed({},{})", kind, idx));
    }

    fn complete_attempt(&mut self, action: &Value) {
        let ai = action
            .get("attempt_index")
            .and_then(|v| v.as_i64())
            .or_else(|| {
                self.full_state
                    .get("attempt_index")
                    .and_then(|v| v.as_i64())
            })
            .unwrap_or(0);
        self.full_state["attempt_index"] = json!(ai);

        let jstr = self.nev.join("|");
        let mut hasher = Sha256::new();
        hasher.update(jstr.as_bytes());
        let hash = format!("sha256:{}", hex::encode(hasher.finalize()));
        self.full_state["event_log_hash"] = json!(hash);

        self.nev.push(format!("ScoreSummaryEmitted({})", ai));
        self.nev.push(format!("AttemptCompleted({})", ai));
    }

    fn parse_action(action: &Value) -> Value {
        if action.is_object() {
            return action.clone();
        }
        let raw = action.as_str().unwrap().trim();
        if let Some((action_type, value)) = raw.split_once(':') {
            match action_type {
                "select_deck" => json!({"type": action_type, "archetype": value}),
                "play" => json!({"type": action_type, "card_id": value}),
                "travel" => json!({"type": action_type, "location_id": value}),
                "test" | "interact" => json!({"type": action_type, "objective_id": value}),
                "write_note" => json!({"type": action_type, "text": value}),
                _ => json!({"type": action_type, "value": value}),
            }
        } else {
            json!({"type": raw})
        }
    }

    fn step(&mut self, action: &Value) {
        let parsed = Self::parse_action(action);
        if self.private.terminated || self.private.truncated {
            self.rule_violation("terminal");
            return;
        }
        self.private.step_index += 1;
        self.private.reward_last = 0.0;

        let action_type = parsed["type"].as_str().unwrap_or("");

        match action_type {
            "start_day" => self.start_day(&parsed),
            "choose_ranger" => self.choose_ranger(&parsed),
            "choose_role" => self.choose_role(&parsed),
            "record_campaign_entry" => self.record_campaign_entry(&parsed),
            "select_deck" => self.select_deck(parsed["archetype"].as_str().unwrap_or(""), true),
            "draw" => self.draw_card(&parsed),
            "discard" => self.discard_card(&parsed),
            "fatigue" => self.fatigue_action(&parsed),
            "soothe" => self.soothe_action(&parsed),
            "take_injury" => self.take_injury(&parsed),
            "add_malady" => self.add_malady(&parsed),
            "play" | "play_card" => {
                self.play_card(parsed["card_id"].as_str().unwrap_or(""), &parsed)
            }
            "spend_energy" => self.spend_energy(&parsed),
            "commit_card" => self.commit_card(&parsed),
            "resolve_test" => self.resolve_test_action(&parsed),
            "resolve_challenge" => self.resolve_challenge(&parsed),
            "exhaust" => self.set_ready_state(&parsed, false),
            "ready" => self.set_ready_state(&parsed, true),
            "build_path_deck" => self.build_path_deck(&parsed),
            "draw_path_card" => self.draw_path_card(&parsed),
            "place_path_card" => self.place_path_card(&parsed),
            "check_range" => self.check_range(&parsed),
            "travel" => self.travel(parsed["location_id"].as_str().unwrap_or(""), &parsed),
            "test" => self.test_objective(parsed["objective_id"].as_str().unwrap_or(""), &parsed),
            "interact" => self.interact(parsed["objective_id"].as_str().unwrap_or(""), &parsed),
            "attach_card" => self.attach_card(&parsed),
            "add_progress" => self.token_action(&parsed, "progress_tokens", "ProgressAdded"),
            "add_harm" => self.token_action(&parsed, "harm_tokens", "HarmAdded"),
            "change_presence" => self.token_action(&parsed, "presence_tokens", "PresenceChanged"),
            "clear_card" => self.clear_card(&parsed),
            "rest" => self.rest(&parsed),
            "end_round" => self.round_event(&parsed, "RoundEnded"),
            "refresh" => self.refresh(&parsed),
            "choose_travel" => self.choose_travel(&parsed),
            "end_day" => self.end_day(&parsed),
            "resolve_trigger" => self.resolve_trigger(&parsed),
            "choose_option" => self.choose_option(&parsed),
            "apply_effect" => self.apply_effect(&parsed),
            "set_active_ranger" => self.set_active_ranger(&parsed),
            "assist_test" => self.assist_test(&parsed),
            "move_ranger_area" => self.move_ranger_area(&parsed),
            "write_note" => self.write_note(parsed["text"].as_str().unwrap_or(""), &parsed),
            "expose_reflection" => self.expose_reflection_action(&parsed),
            "complete_attempt" => self.complete_attempt(&parsed),
            _ => self.rule_violation(&format!("unknown_action:{}", action_type)),
        }
        self.check_limits();
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let entry: Value = serde_json::from_str(&input).unwrap();

    // Check if it's a fixture scenario (doesn't have schema) or full task
    let is_fixture = !entry.as_object().unwrap().contains_key("schema")
        && entry.as_object().unwrap().contains_key("scenario_id");

    let task;
    let mut actions = Vec::new();
    let mut restore_then_actions = Vec::new();
    let mut checkpoint_after = -1;

    if is_fixture {
        task = json!({
            "schema": "gamebench.earthborne_rangers.scenarios.v1",
            "task_id": entry.get("task_id").unwrap_or(&entry["scenario_id"]),
            "scenario_id": entry["scenario_id"],
            "seed": entry.get("seed").unwrap_or(&json!(0)),
            "ranger_id": entry.get("ranger_id").unwrap_or(&json!("synthetic_ranger")),
            "default_archetype": entry.get("default_archetype").unwrap_or(&json!("pathfinder")),
            "starting_location": entry.get("starting_location").unwrap_or(&json!("trailhead")),
            "max_steps": entry.get("max_steps").unwrap_or(&json!(24)),
            "max_days": entry.get("max_days").unwrap_or(&json!(5)),
            "objectives": entry.get("objectives"),
            "rules": entry.get("rules").unwrap_or(&json!({})),
            "reflexion": entry.get("reflexion").unwrap_or(&json!({})),
        });
        if let Some(arr) = entry.get("actions").and_then(|a| a.as_array()) {
            actions = arr.clone();
        }
        if let Some(a) = entry.get("checkpoint_after").and_then(|v| v.as_i64()) {
            checkpoint_after = a;
        }
        if let Some(arr) = entry.get("restore_then_actions").and_then(|a| a.as_array()) {
            restore_then_actions = arr.clone();
        }
    } else {
        task = entry.clone();
        if let Some(arr) = entry.get("actions").and_then(|a| a.as_array()) {
            actions = arr.clone();
        }
        if let Some(a) = entry.get("checkpoint_after").and_then(|v| v.as_i64()) {
            checkpoint_after = a;
        }
        if let Some(arr) = entry.get("restore_then_actions").and_then(|a| a.as_array()) {
            restore_then_actions = arr.clone();
        }
    }

    let mut engine = Engine::new(&task);
    let mut checkpoint_engine: Option<Engine> = None;

    for (index, action) in actions.iter().enumerate() {
        let idx = (index + 1) as i64;
        if engine.private.terminated || engine.private.truncated {
            break;
        }
        engine.step(action);
        if checkpoint_after == idx {
            checkpoint_engine = Some(engine.clone());
        }
    }

    if let Some(chk) = checkpoint_engine {
        // Swap engine with the cloned one to simulate restore
        engine = chk;
        for action in restore_then_actions {
            if engine.private.terminated || engine.private.truncated {
                break;
            }
            engine.step(&action);
        }
    }

    println!("{}", json!({"events": engine.nev}));
}

