    fn draw_card(&mut self, _action: &Value) {
        if self.private.deck.is_empty() {
            self.rule_violation("deck_not_selected");
            return;
        }
        let card_id = self.private.deck[self.private.deck_index % self.private.deck.len()].clone();
        self.private.deck_index += 1;
        self.public.hand.push(card_id.clone());
        self.full_state["hand"] = json!(self.public.hand);
        self.unlock("first_card_drawn");
        self.nev.push(format!("CardDrawn({})", card_id));
    }

    fn play_card(&mut self, card_id: &str, _action: &Value) {
        if !self.public.hand.contains(&card_id.to_string()) {
            self.rule_violation(&format!("card_not_in_hand:{}", card_id));
            return;
        }
        if let Some(pos) = self.public.hand.iter().position(|x| x == card_id) {
            self.public.hand.remove(pos);
        }
        self.public.play_area.push(card_id.to_string());
        self.full_state["hand"] = json!(self.public.hand);
        self.private.cards_played.push(card_id.to_string());
        self.unlock("first_card_played");

        let unique_cards: HashSet<_> = self.private.cards_played.iter().collect();
        if unique_cards.len() >= 5 {
            self.unlock("card_diversity_5");
        }

        self.nev.push(format!("CardPlayed({})", card_id));

        let effects = get_card_effects(card_id);
        if !effects.is_empty() {
            self.apply_effect_list(
                &effects,
                &format!("card:{}", card_id),
                &format!("CardEffect({})", card_id),
            );
        } else {
            let fatigue_cost = get_card_fatigue_cost(card_id);
            if fatigue_cost > 0 {
                self.take_fatigue(
                    fatigue_cost,
                    &format!("CardFatigue({},{})", card_id, fatigue_cost),
                );
            }
            let recover = get_card_recover(card_id);
            if recover > 0 {
                self.recover_fatigue(recover, &format!("CardRecovered({},{})", card_id, recover));
            }
            let progress = get_card_progress(card_id);
            if progress > 0 {
                let obj = self.nearest_incomplete_objective();
                self.apply_progress(&obj, progress);
            }
        }
    }

    fn apply_effect_list(&mut self, effects: &[Value], _source: &str, label: &str) {
        for (index, effect) in effects.iter().enumerate() {
            if !effect.is_object() {
                self.nev
                    .push(format!("EffectResolved({}:{})", label, index));
                continue;
            }
            let kind = effect
                .get("kind")
                .and_then(|v| v.as_str())
                .unwrap_or("effect");
            let amount = effect.get("amount").and_then(|v| v.as_i64()).unwrap_or(1) as i32;
            if kind == "fatigue" {
                self.take_fatigue(amount, &format!("{}:Fatigue({})", label, amount));
            } else if kind == "recover" {
                self.recover_fatigue(amount, &format!("{}:Recovered({})", label, amount));
            } else if kind == "progress" {
                let obj = effect
                    .get("objective_id")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| self.nearest_incomplete_objective());
                self.apply_progress(&obj, amount);
            } else {
                // Not fully implementing all effect branches for synthetic eval unless needed
                self.nev.push(format!("EffectResolved({})", kind));
            }
        }
    }

