    fn draw_path_card(&mut self, action: &Value) {
        let mut card_id = action
            .get("card_id")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());
        if card_id.is_none() {
            let deck = self.full_state["path_deck"].as_array_mut().unwrap();
            if !deck.is_empty() {
                card_id = Some(deck.remove(0).as_str().unwrap().to_string());
            }
        }
        let cid = card_id.unwrap_or_default();
        if !cid.is_empty() {
            self.full_state["path_discard"]
                .as_array_mut()
                .unwrap()
                .push(json!(cid));
        }
        self.nev.push(format!("PathCardRevealed({})", cid));
    }

    fn place_path_card(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let zone = action
            .get("zone")
            .and_then(|v| v.as_str())
            .unwrap_or("within_reach");
        let kind = action
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("path");
        self.full_state[zone]
            .as_array_mut()
            .unwrap()
            .push(json!(card_id));
        self.full_state["world_cards"][card_id] = json!({"zone": zone, "kind": kind});
        let mut traits = action
            .get("traits")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default();
        if traits.is_empty() && card_id == "path_obstacle" {
            traits = vec![json!("obstacle")];
        }
        if !traits.is_empty() {
            self.full_state["traits"][card_id] = json!(traits);
        }
        if kind == "obstacle"
            || traits.iter().any(|v| v.as_str() == Some("obstacle"))
            || action
                .get("obstacle")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        {
            let obs = self.full_state["obstacles"].as_array_mut().unwrap();
            if !obs.iter().any(|v| v.as_str() == Some(card_id)) {
                obs.push(json!(card_id));
            }
        }
        self.nev
            .push(format!("PathCardPlaced({},{})", card_id, zone));
        self.nev
            .push(format!("WorldCardEntered({},{})", card_id, zone));
    }

    fn check_range(&mut self, action: &Value) {
        let card_id = action.get("card_id").and_then(|v| v.as_str()).unwrap_or("");
        let in_reach = self.full_state["within_reach"]
            .as_array()
            .unwrap()
            .iter()
            .any(|v| v.as_str() == Some(card_id));
        let reachable = action
            .get("reachable")
            .and_then(|v| v.as_bool())
            .unwrap_or(in_reach);
        if !reachable
            && action
                .get("blocked_by_obstacle")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
        {
            self.private.obstacle_blocked_seen = true;
            self.nev.push(format!("ObstacleBlocked({})", card_id));
        }
        let bstr = if reachable { "True" } else { "False" };
        self.nev.push(format!("RangeChecked({},{})", card_id, bstr));
    }

    fn travel(&mut self, location_id: &str, _action: &Value) {
        self.public.location_id = location_id.to_string();
        let fatigue = get_location_travel_fatigue(location_id);
        if fatigue > 0 {
            self.take_fatigue(
                fatigue,
                &format!("TravelFatigue({},{})", location_id, fatigue),
            );
        }
        self.unlock("first_travel");
        if self.private.obstacle_blocked_seen {
            self.unlock("clear_obstacle");
        }
        self.nev.push(format!("LocationChanged({})", location_id));
    }

    fn test_objective(&mut self, objective_id: &str, _action: &Value) {
        if !self.private.objective_targets.contains_key(objective_id) {
            self.rule_violation(&format!("unknown_objective:{}", objective_id));
            return;
        }
        let fatigue = if self.public.fatigue >= 3 { 1 } else { 0 };
        if fatigue > 0 {
            self.take_fatigue(
                fatigue,
                &format!("TestFatigue({},{})", objective_id, fatigue),
            );
        }
        self.nev
            .push(format!("TestResolved({},success)", objective_id));
        self.unlock("first_test_resolved");
        self.unlock("pass_test");
        self.apply_progress(objective_id, 1);
    }

    fn interact(&mut self, objective_id: &str, _action: &Value) {
        if let Some(expected) = self.private.objective_locations.get(objective_id) {
            if expected != &self.public.location_id {
                self.rule_violation(&format!(
                    "wrong_location:{}:{}",
                    objective_id, self.public.location_id
                ));
                return;
            }
        } else {
            self.rule_violation(&format!("unknown_objective:{}", objective_id));
            return;
        }
        self.nev
            .push(format!("TestResolved({},interact)", objective_id));
        self.unlock("first_test_resolved");
        self.unlock("pass_test");
        self.apply_progress(objective_id, 1);
    }

